package cn.huankan.collector;
import java.util.*;import java.time.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;import com.fasterxml.jackson.databind.*;
@Service public class BlsCollector {
 private final JdbcTemplate db;private final EvidenceService evidence;private final CollectorGuard guard;private final TransactionTemplate tx;private final ObjectMapper json;public BlsCollector(JdbcTemplate db,EvidenceService e,CollectorGuard g,org.springframework.transaction.PlatformTransactionManager manager,ObjectMapper j){this.db=db;evidence=e;guard=g;tx=new TransactionTemplate(manager);json=j;}
 public Object status(){return Map.of("series",db.queryForList("SELECT * FROM bls_series_config ORDER BY id"),"requests_last_24h",db.queryForObject("SELECT count(*) FROM bls_request WHERE started_at>now()-interval '24 hours'",Long.class),"daily_limit",25,"series_limit",25,"year_limit",10,"requests",db.queryForList("SELECT id,started_at,http_status,api_status,error,sha256 FROM bls_request ORDER BY started_at DESC LIMIT 25"),"observations",db.queryForObject("SELECT count(*) FROM bls_observation",Long.class),"state","BLS月度统计；观测月份不是发布时间，首次发布时间未知保持空值");}
 public UUID reserve(UUID job,String body){return tx.execute(s->{db.execute("SELECT pg_advisory_xact_lock(742040)");if(db.queryForObject("SELECT count(*) FROM bls_request WHERE started_at>now()-interval '24 hours'",Long.class)>=25)throw new IllegalStateException("BLS_QUOTA_EXHAUSTED");if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM bls_request WHERE (http_status=429 OR api_status='REQUEST_NOT_PROCESSED') AND started_at>now()-interval '24 hours')",Boolean.class)))throw new IllegalStateException("BLS_COOLDOWN_AFTER_LIMIT_RESPONSE");UUID id=UUID.randomUUID();db.update("INSERT INTO bls_request(id,job_id,request_body) VALUES(?,?,?::jsonb)",id,job,body);return id;});}
 public Object collect(List<String> series,int startYear,int endYear){if(series==null||series.isEmpty()||series.size()>25||new HashSet<>(series).size()!=series.size()||startYear<1900||endYear<startYear||endYear-startYear>9||endYear>LocalDate.now(ZoneOffset.UTC).getYear())throw new IllegalArgumentException("BLS序列数量、年份或重复配置无效");for(String id:series)if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM bls_series_config WHERE id=? AND verified AND enabled)",Boolean.class,id)))throw new IllegalArgumentException("BLS序列官方定义或单位尚未核实");if(!Boolean.TRUE.equals(db.queryForObject("SELECT status='APPROVED' AND access_allowed AND storage_allowed AND display_allowed AND (valid_until IS NULL OR valid_until>now()) FROM source_license WHERE source_id='BLS'",Boolean.class)))throw new IllegalStateException("BLS许可待核验");
 try(var lease=guard.acquire("BLS")){if(lease==null)throw new IllegalStateException("BLS采集已有任务运行");UUID job=UUID.randomUUID();db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'BLS','RUNNING')",job);UUID request=null;Integer http=null;long started=System.nanoTime();try{String body=json.writeValueAsString(Map.of("seriesid",series,"startyear",String.valueOf(startYear),"endyear",String.valueOf(endYear)));request=reserve(job,body);guard.request("api.bls.gov");var req=HttpRequest.newBuilder(URI.create(BlsSourceAdapter.URL)).timeout(Duration.ofSeconds(30)).header("Content-Type","application/json").header("User-Agent","HUANKAN/0.1 official economic statistics research").POST(HttpRequest.BodyPublishers.ofString(body)).build();var r=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).followRedirects(HttpClient.Redirect.NEVER).build().send(req,HttpResponse.BodyHandlers.ofInputStream());http=r.statusCode();byte[] bytes;try(var in=r.body()){bytes=in.readNBytes(4194305);}if(bytes.length>4194304)throw new IllegalArgumentException("BLS_RESPONSE_TOO_LARGE");String apiStatus;try{apiStatus=json.readTree(bytes).path("status").asText("MISSING");}catch(Exception e){apiStatus="INVALID_JSON";}db.update("UPDATE bls_request SET http_status=?,api_status=?,raw_response=?,sha256=?,finished_at=clock_timestamp() WHERE id=?",http,apiStatus,bytes,EvidenceService.hash(bytes),request);db.update("INSERT INTO http_request_observation(source_id,endpoint,attempted_at,completed_at,status,duration_ms,response_bytes) SELECT 'BLS',?,started_at,now(),?,?,? FROM bls_request WHERE id=?",BlsSourceAdapter.URL,http,(System.nanoTime()-started)/1000000,bytes.length,request);if(http!=200)throw new IllegalStateException("HTTP_"+http);var observations=BlsSourceAdapter.observations(bytes);if(observations.stream().anyMatch(o->!series.contains(o.series())||o.date().getYear()<startYear||o.date().getYear()>endYear)||!observations.stream().map(BlsSourceAdapter.Observation::series).collect(java.util.stream.Collectors.toSet()).containsAll(series))throw new IllegalArgumentException("BLS响应序列或年份与请求不一致");var result=persist(job,request,bytes,observations);db.update("UPDATE ingestion_job SET status='SUCCESS',finished_at=now(),http_status=?,fetched_count=?,new_count=?,duplicate_count=?,duration_ms=? WHERE id=?",http,result.get("fetched"),result.get("inserted"),result.get("duplicates"),(System.nanoTime()-started)/1000000,job);return Map.of("job_id",job,"request_id",request,"result",result);
 }catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();String message=Objects.toString(e.getMessage(),e.getClass().getSimpleName());if(http==null&&request!=null)db.update("INSERT INTO http_request_observation(source_id,endpoint,attempted_at,completed_at,duration_ms,error,failure_kind) SELECT 'BLS',?,started_at,now(),?,?,? FROM bls_request WHERE id=?",BlsSourceAdapter.URL,(System.nanoTime()-started)/1000000,message,CollectorGuard.failure(e),request);if(request!=null)db.update("UPDATE bls_request SET error=?,finished_at=clock_timestamp() WHERE id=?",message,request);db.update("UPDATE ingestion_job SET status='FAILED',finished_at=now(),http_status=?,error_code=?,error_detail=? WHERE id=?",http,CollectorGuard.failure(e),message,job);return Map.of("job_id",job,"status","FAILED","error",message,"inserted",db.queryForObject("SELECT count(*) FROM raw_evidence WHERE job_id=?",Long.class,job));}
 }catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("BLS采集锁异常",e);}}
 public Map<String,Integer> persist(UUID job,UUID request,byte[] bytes,List<BlsSourceAdapter.Observation> observations){return tx.execute(s->{UUID response=UUID.randomUUID();db.update("INSERT INTO official_response(id,source_id,job_id,url,response_status,raw_content,sha256) VALUES(?,'BLS',?,?,200,?,?)",response,job,BlsSourceAdapter.URL,bytes,EvidenceService.hash(bytes));int inserted=0;Instant seen=Instant.now();for(var o:observations){var config=db.queryForMap("SELECT * FROM bls_series_config WHERE id=? AND verified AND enabled",o.series());String title=config.get("title").toString()+" · "+o.date()+" · "+o.rawValue()+" · "+o.footnotes();String metadata;try{metadata=json.writeValueAsString(config);}catch(Exception e){throw new IllegalArgumentException(e);}db.update("INSERT INTO macro_series(id,source_id,flow,series_key,title,units,frequency,metadata,response_id) VALUES(?,'BLS','BLS_V1',?,?,?,'M',?::jsonb,?) ON CONFLICT(id) DO UPDATE SET response_id=excluded.response_id,updated_at=now()",o.series(),o.series(),config.get("title"),config.get("unit"),metadata,response);String document=o.series()+":"+o.date();int n=evidence.persist("BLS",job,bytes,List.of(new SourceAdapter.Item(document,title,BlsSourceAdapter.URL,null,"美国官方宏观数据")),seen,true);inserted+=n;UUID id=db.queryForObject("SELECT id FROM raw_evidence WHERE source_id='BLS' AND source_document_id=? ORDER BY revision DESC LIMIT 1",UUID.class,document);db.update("INSERT INTO macro_observation(evidence_id,series_id,observation_date,value,observation_status,version) SELECT ?,?,?,?, ?,revision FROM raw_evidence WHERE id=? ON CONFLICT(evidence_id) DO NOTHING",id,o.series(),java.sql.Date.valueOf(o.date()),o.value(),o.releaseStatus(),id);db.update("INSERT INTO bls_observation(evidence_id,request_id,period,raw_value,footnotes,release_status,payload) VALUES(?,?,?,?,?::jsonb,?,?::jsonb) ON CONFLICT(evidence_id) DO NOTHING",id,request,o.period(),o.rawValue(),o.footnotes().toString(),o.releaseStatus(),o.payload().toString());db.update("INSERT INTO response_evidence(response_id,evidence_id) VALUES(?,?) ON CONFLICT DO NOTHING",response,id);if(n>0){var fields=new LinkedHashMap<String,Object>();fields.put("indicator_id",o.series());fields.put("observation_period",o.date().toString());fields.put("period_label",o.date().toString().substring(0,7));fields.put("actual_value",o.value());fields.put("raw_value",o.rawValue());fields.put("unit",config.get("unit"));fields.put("frequency","M");fields.put("seasonal_adjustment",config.get("adjustment"));fields.put("footnotes",o.footnotes());fields.put("release_status",o.releaseStatus());fields.put("source_published_at",null);fields.put("market_expectation",null);fields.put("source","BLS");fields.put("interpretation","月度官方观测，月初日期仅用于月份存储；不代表首次发布时间；非农序列为就业总人数，不是新增就业人数");UUID fact=UUID.randomUUID();int version=db.queryForObject("SELECT revision FROM raw_evidence WHERE id=?",Integer.class,id);String encoded;try{encoded=json.writeValueAsString(fields);}catch(Exception e){throw new IllegalArgumentException(e);}db.update("INSERT INTO fact_candidate(id,fact_key,version,fact_type,observation_id,fields,extraction_method,verification_status) VALUES(?,?,?,'MACRO_OBSERVATION',?,?::jsonb,'BLS JSON逐字段校验-1.0','FIELD_MATCHED')",fact,"macro:"+document,version,id,encoded);db.update("INSERT INTO fact_evidence VALUES(?,?,?,?)",fact,id,o.literal(),"JSON:Results/series[seriesID="+o.series()+"]/data[year="+o.date().getYear()+",period="+o.period()+"]");db.update("INSERT INTO fact_revision SELECT ?,id,'后续采集发现官方值或脚注变化；源站修订公布时刻未知' FROM fact_candidate WHERE fact_key=? AND version<? ORDER BY version DESC LIMIT 1",fact,"macro:"+document,version);}}
 return Map.of("fetched",observations.size(),"inserted",inserted,"duplicates",observations.size()-inserted);});}
}
